diff --git a/client.mjs b/client.mjs
index 9ad81d0..2d05a25 100644
--- a/client.mjs
+++ b/client.mjs
@@ -2,0 +3,2 @@
+import { sleep as realSleep } from './util.mjs';
+
@@ -12,4 +14,30 @@ export class HttpError extends Error {
-export async function fetchJson(url, { fetch = globalThis.fetch, headers = {} } = {}) {
-  const res = await fetch(url, { headers: { accept: 'application/json', ...headers } });
-  if (!res.ok) throw new HttpError(res.status, url);
-  return res.json();
+export async function fetchJson(url, { fetch = globalThis.fetch, sleep = realSleep, headers = {} } = {}) {
+  const maxAttempts = 3;
+  let lastError;
+
+  for (let attempt = 1; attempt <= maxAttempts; attempt++) {
+    try {
+      const res = await fetch(url, { headers: { accept: 'application/json', ...headers } });
+      if (!res.ok) {
+        const err = new HttpError(res.status, url);
+        // Don't retry 4xx errors
+        if (res.status >= 400 && res.status < 500) throw err;
+        lastError = err;
+      } else {
+        return res.json();
+      }
+    } catch (err) {
+      // Retry on network errors (connection drops, timeouts, etc.)
+      // 4xx errors already thrown above, so this catches 5xx and network errors
+      if (err instanceof HttpError && err.status >= 400 && err.status < 500) throw err;
+      lastError = err;
+    }
+
+    // If we have attempts left, wait before retrying
+    if (attempt < maxAttempts) {
+      const backoffMs = Math.pow(2, attempt - 1) * 100; // 100ms, 200ms
+      await sleep(backoffMs);
+    }
+  }
+
+  throw lastError;
