index 9ad81d0..b2fc20f 100644
--- a/client.mjs
+++ b/client.mjs
@@ -1 +1 @@
-// Thin JSON client for the inventory upstream.
+import { sleep as realSleep } from './util.mjs';
@@ -12,4 +12,38 @@ export class HttpError extends Error {
-export async function fetchJson(url, { fetch = globalThis.fetch, headers = {} } = {}) {
-  const res = await fetch(url, { headers: { accept: 'application/json', ...headers } });
-  if (!res.ok) throw new HttpError(res.status, url);
-  return res.json();
+export async function fetchJson(url, { fetch = globalThis.fetch, sleep = realSleep, headers = {} } = {}) {
+  const maxAttempts = 3;
+  const backoffMs = 100;
+  
+  for (let attempt = 0; attempt < maxAttempts; attempt++) {
+    try {
+      const res = await fetch(url, { headers: { accept: 'application/json', ...headers } });
+      if (!res.ok) {
+        // Don't retry 4xx errors
+        if (res.status >= 400 && res.status < 500) {
+          throw new HttpError(res.status, url);
+        }
+        // For 5xx, retry if not last attempt
+        if (attempt < maxAttempts - 1) {
+          await sleep(backoffMs * (attempt + 1));
+          continue;
+        }
+        throw new HttpError(res.status, url);
+      }
+      return res.json();
+    } catch (err) {
+      // If it's an HttpError for 4xx, rethrow immediately
+      if (err instanceof HttpError && err.status >= 400 && err.status < 500) {
+        throw err;
+      }
+      // Retry on connection errors or 5xx (but only if not last attempt)
+      if (attempt < maxAttempts - 1) {
+        await sleep(backoffMs * (attempt + 1));
+        continue;
+      }
+      // Last attempt, rethrow the error
+      if (err instanceof HttpError) {
+        throw err;
+      }
+      // Re-throw connection error on last attempt
+      throw err;
+    }
+  }
