+    if (attempts < 3) return respond(503);
+    return respond(200, { sku: 'A1' });
+  };
+  const item = await fetchJson('https://x/items/A1', { fetch, sleep: async (ms) => naps.push(ms) });
+  assert.equal(item.sku, 'A1');
+  assert.equal(attempts, 3);
+  assert.deepEqual(naps, [100, 200]); // backoff: 100ms, 200ms
+});
+
+test('does not retry 404', async () => {
+  let attempts = 0;
+  const fetch = async () => { attempts++; return respond(404); };
+  await assert.rejects(fetchJson('https://x/items/nope', { fetch }), (err) => err instanceof HttpError && err.status === 404);
+  assert.equal(attempts, 1);
+});
+
+test('retries on connection drop', async () => {
+  let attempts = 0;
+  const naps = [];
+  const fetch = async () => {
+    attempts++;
+    if (attempts < 3) throw new Error('Connection dropped');
+    return respond(200, { sku: 'A1' });
+  };
+  const item = await fetchJson('https://x/items/A1', { fetch, sleep: async (ms) => naps.push(ms) });
+  assert.equal(item.sku, 'A1');
+  assert.equal(attempts, 3);
+  assert.deepEqual(naps, [100, 200]);
+});
+
+test('throws after 3 attempts on 503', async () => {
+  let attempts = 0;
+  const fetch = async () => { attempts++; return respond(503); };
+  await assert.rejects(fetchJson('https://x/items/A1', { fetch }), (err) => err instanceof HttpError && err.status === 503);
+  assert.equal(attempts, 3);
+});

