+export async function fetchJson(url, { fetch = globalThis.fetch, sleep = realSleep, headers = {} } = {}) {
+  let lastError;
+  const maxAttempts = 3;
+
+  for (let attempt = 0; attempt < maxAttempts; attempt++) {
+    try {
+      const res = await fetch(url, { headers: { accept: 'application/json', ...headers } });
+      if (res.ok) {
+        return res.json();
+      }
+      // Response is not ok
+      const err = new HttpError(res.status, url);
+      if (res.status >= 400 && res.status < 500) {
+        // 4xx error - don't retry
+        throw err;
+      }
+      // 5xx error - retry
+      lastError = err;
+    } catch (err) {
+      // Check if it's a 4xx HttpError (don't retry)
+      if (err instanceof HttpError && err.status >= 400 && err.status < 500) {
+        throw err;
+      }
+      // Other errors (network, 5xx, etc.) - retry
+      lastError = err;
+    }
+
+    // If we have more attempts, sleep before retry
+    if (attempt < maxAttempts - 1) {
+      await sleep(Math.pow(2, attempt) * 100); // exponential backoff: 100ms, 200ms, 400ms
+    }
+  }
+
+  throw lastError;
